import './App.css';

function App() {
  function App() {
  return (
    <div>
      <nav>
        <h2>John Doe</h2>
      </nav>

      <section>
        <h1>Frontend Developer</h1>
        <p>React & Web Design</p>
      </section>

      <section>
        <h2>Projects</h2>

        <div>
          <h3>Project 1</h3>
          <p>Portfolio website</p>
        </div>

        <div>
          <h3>Project 2</h3>
          <p>Weather app</p>
        </div>
      </section>
    </div>
  );
}
}

export default App;
